/// Result of a wait (C# `WaitForSingleObjectEx` returned a raw `uint`; the renderer only compared it with `WaitObject0`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WaitResult {
    /// `WAIT_OBJECT_0` (0): the object is signaled.
    Signaled,
    /// `WAIT_TIMEOUT` (0x102).
    Timeout,
    /// `WAIT_ABANDONED` (0x80).
    Abandoned,
    /// `WAIT_IO_COMPLETION` (0xC0): an alertable wait was ended by an APC.
    IoCompletion,
    /// `WAIT_FAILED` (0xFFFFFFFF) or any other value.
    Failed,
}

impl WaitResult {
    /// Maps the raw `WAIT_EVENT` value.
    #[must_use]
    pub fn from_raw(raw: u32) -> Self {
        todo!("W8-11f")
    }

    /// C# `result == GraphicsKernel32.WaitObject0`.
    #[must_use]
    pub fn is_signaled(self) -> bool {
        todo!("W8-11f")
    }
}

